(function(){
  'use strict';
  const E=window.MUGA,G=window.MUGAEventGuide,$=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog');
  let local=null,idb=null;try{local=window.localStorage;}catch{}try{idb=window.indexedDB;}catch{}
  const saves=window.MUGAStorage.create({local,indexedDB:idb,validate:E.validateSave,serialize:E.serializeSave});
  let state=null,tab='office',sub='roster',marketFilter='ALL',activeSlot=1,slots=[],saving='已保存',busy=false,stop=false,progress='',saveProblem=false,selectedOption=null,decisionBusy=false;
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>`${n<0?'−':''}€${Math.abs(n)>=100?(Math.abs(n)/100).toFixed(2)+'亿':Math.abs(n)>=1?Math.abs(n).toFixed(1)+'百万':Math.round(Math.abs(n)*100)+'万'}`;
  const year=s=>`${E.seasonYear(s)}/${String(E.seasonYear(s)+1).slice(-2)}`;
  const phase=s=>({summer:'夏季转会窗',winter:'冬季转会窗',league:`联赛第 ${s.round}/38 轮`,review:'赛季总结',ended:'任期归档'})[s.phase];
  const paths={office:'M3 21h18M5 21V7l7-4 7 4v14M9 21v-6h6v6M8 9h1m6 0h1M8 12h1m6 0h1',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',market:'M7 7h14l-4-4m4 4-4 4M17 17H3l4 4m-4-4 4-4',season:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2M8 14h2m4 0h2m-8 4h2',club:'M3 7h18M5 7v12m5-12v12m4-12v12m5-12v12M2 21h20M12 2 2 7h20z',arrow:'M5 12h14m-6-6 6 6-6 6',play:'m8 5 11 7-11 7z',save:'M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h12l4 4v12a2 2 0 0 1-2 2M7 3v6h10V3M7 21v-8h10v8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',help:'M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3m.08 4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12M6 18 18 6',wallet:'M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6m18 7h-5v4h5',chart:'M3 3v18h18M7 14l4-4 4 2 5-7',trophy:'M8 3h8v7a4 4 0 0 1-8 0V3m0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 2v5m-4 2h8',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-8 13h4',person:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',download:'M12 3v12m-5-5 5 5 5-5M5 16v5h14v-5',upload:'M12 16V4m-5 5 5-5 5 5M5 16v5h14v-5',share:'M18 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6M6 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6m12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6M8.6 10.5l6.8-4M8.6 13.5l6.8 4',check:'m5 12 4 4L19 6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',refresh:'M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 14 6M4 12a8 8 0 0 0 14 6'};
  function icon(n){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.bell}"/></svg>`;}
  function btn(label,action,cls='',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;}
  function brand(){return '<div class="brand"><div class="brand-mark">M</div><div><div class="brand-name">MUGA</div><div class="brand-sub">REBUILD. REPEAT.</div></div></div>';}
  function stadium(){return '<div class="stadium-art" aria-hidden="true"><div class="stadium-ring"><div class="pitch"></div></div></div>';}
  function seasonText(){return `${year(state)} · ${phase(state)}`;}
  function toast(msg,bad=false){const div=document.createElement('div');div.className='toast'+(bad?' bad':'');div.textContent=msg;$('#toasts').append(div);setTimeout(()=>div.remove(),5500);}
  function openModal(title,body,footer=''){if(dialog.open)dialog.close();dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" aria-label="关闭" data-action="close">${icon('close')}</button></div><div class="dialog-body">${body}<div class="dialog-error" id="dialog-error" role="alert"></div></div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;dialog.showModal();}
  function modalError(t){const d=$('#dialog-error');if(d)d.textContent=t;else toast(t,true);}
  function annotateEvent(){if(state?.event&&!state.event.context){const info=G.info(state);state.event.context={source:info.source,reason:info.reason};}}
  async function save(){if(!state)return true;annotateEvent();saving='正在保存';document.querySelectorAll('[data-save-label]').forEach(el=>el.textContent=saving);const result=await saves.save(state,activeSlot);slots=saves.records();saveProblem=!result.ok;saving=result.ok?(result.indexedDB?'已自动保存':'备份已保存'):'保存失败';document.querySelectorAll('[data-save-label]').forEach(el=>el.textContent=saving);if(!result.ok)toast('此浏览器未能保存进度，请立即导出备份。',true);return result.ok;}
  function checkpoint(){if(state){annotateEvent();saves.checkpoint(state,activeSlot);}}
  async function commit(result,{close=false,quiet=false}={}){if(result&&!result.ok){modalError(result.message);if(!dialog.open)toast(result.message,true);return false;}await save();if(close&&dialog.open)dialog.close();render();if(result?.message&&!quiet)toast(result.message);return true;}
  function showSetup(){const params=new URLSearchParams(location.search);const seed=params.get('seed')||'MUGA-2026';app.innerHTML=`<div class="setup-shell"><section class="setup-story">${brand()}<div class="setup-story-main"><div class="eyebrow">CLUB CRISIS & COMEDY</div><h1>伟大复兴。<br><em>从你背锅开始。</em></h1><p>欢迎执掌曼联。你的前任也觉得问题不大。<br>修屋顶、卖希望、周旋董事会，让下一次重建<br>不再从换掉你开始。</p><div class="setup-metrics"><div><strong>20</strong><span>个赛季的长期计划</span></div><div><strong>38</strong><span>轮联赛的现实检验</span></div><div><strong>∞</strong><span>种体面的解释</span></div></div></div>${stadium()}<div class="setup-footer">2026/27 真实名单开局 · 经营闹剧 v0.6 · 独立球迷作品</div></section><section class="setup-form"><div class="setup-form-inner"><div class="eyebrow">YOUR FIRST DAY</div><h2>董事会正在等你签字</h2><p class="intro">合同保证你有机会。能待多久，合同没说。</p><form id="new-game-form"><div class="form-field"><label for="director-name">你的名字</label><input id="director-name" name="director" maxlength="20" value="新任总监" required autocomplete="off"></div><div class="form-row"><div class="form-field"><label for="background">职业背景</label><select id="background"><option value="经理人">职业经理人 · 人脉 +8</option><option value="前球员">前职业球员 · 信任 +8</option><option value="企业CEO">企业 CEO · 信用 +8</option></select></div><div class="form-field"><label for="style">管理风格</label><select id="style"><option>沟通型</option><option>公众型</option><option>理财型</option></select></div></div><div class="form-row"><div class="form-field"><label for="difficulty">经营难度</label><select id="difficulty">${['轻松','标准','挑战'].map(x=>`<option ${x===(params.get('difficulty')||'标准')?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="slot">存档位置</label><select id="slot">${[1,2,3].map(n=>`<option value="${n}" ${n===([1,2,3].find(n=>!slots.some(s=>s.id===n))||1)?'selected':''}>存档 ${n}${slots.some(s=>s.id===n)?' · 已有任期':' · 空'}</option>`).join('')}</select></div></div><div class="form-field"><label for="seed">开局种子 <span class="muted">同种子可重玩同一世界</span></label><input id="seed" value="${esc(seed)}" maxlength="40" required></div><label class="check-label"><input type="checkbox" id="gray" ${params.get('gray')==='1'?'checked':''}>开启灰色事件：私人回扣、虚构掮客和调查风险</label><button class="btn primary w100" type="submit">签下长期计划 ${icon('arrow')}</button></form><p class="tiny muted mt16">名单快照：2026-11-14。身份资料源自ESPN，曼联名单经英超官方核对；能力、工资和估值为游戏设定。第6季起加入虚构新秀。</p><p class="setup-trust">无需登录 · 本地存档 · 真实名单 / 模拟经营</p>${slots.length?`<div class="setup-saves"><div class="label">继续一段未完的重建</div>${slots.sort((a,b)=>a.id-b.id).map(s=>`<button class="save-preview" data-action="load" data-slot="${s.id}"><span><b>${esc(s.state.name)}</b><br><span class="small muted">${year(s.state)} · ${phase(s.state)}</span></span>${icon('arrow')}</button>`).join('')}</div>`:''}<div class="row between mt24"><button class="text-button small muted" data-action="paste-backup">粘贴备份导入</button><button class="text-button small muted" data-action="import">${icon('upload')} 导入备份</button><button class="text-button small muted" data-action="help">怎么玩 ${icon('help')}</button></div></div></section></div>`;}
  function render(){if(!state){showSetup();return;}const names={office:'办公室',team:'球队',market:'转会市场',season:'赛季',club:'俱乐部'};app.innerHTML=`<aside class="sidebar">${brand()}<div class="sidebar-section">DIRECTOR'S DESK</div><nav class="nav" aria-label="主导航">${Object.entries(names).map(([key,name])=>`<button class="nav-btn ${tab===key?'active':''}" data-action="nav" data-tab="${key}">${icon(key)}<span>${name}</span>${key==='office'&&(state.event||unreadNews().length)?`<span class="nav-count">${state.event?'待办':unreadNews().length}</span>`:key==='market'&&state.offers.length?`<span class="nav-count">${state.offers.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><div class="director row"><div class="avatar">${esc(state.name.slice(0,1))}</div><div style="min-width:0"><div class="small truncate">${esc(state.name)}</div><div class="tiny muted">足球总监 · 第 ${state.season} 年</div></div></div><p class="sidebar-quote">“我们充分尊重你的专业判断。<br>因此失败与你独立相关。”</p><div class="tiny muted mt16">LOCAL SAVE ${activeSlot} · v0.6</div></div></aside><div class="main-shell"><header class="topbar"><div class="topbar-path">MUGA / <b>${names[tab]}</b></div><div class="mobile-brand"><div class="brand-mark">M</div><b>MUGA</b></div><div class="topbar-actions"><span class="season-label">${year(state)} <span class="hide-mobile">· ${phase(state)}</span></span><span class="save-status"><span class="dot"></span> <span id="save-label" data-save-label>${saving}</span></span><button class="icon-btn" data-action="help" aria-label="游戏帮助">${icon('help')}</button><button class="icon-btn" data-action="settings" aria-label="设置与存档">${icon('settings')}</button></div></header><main class="content" id="main-content">${saveProblem?`<div class="inline-alert" role="alert">进度尚未保存，请保持页面打开并导出备份。${btn("导出备份","export","ghost compact")}</div>`:""}${handoffBanner()}${!E.realWorld(state)?`<div class="roster-notice"><div><b>真实名单版本已上线</b><p>当前是旧版虚构球队任期。可保留此档，在空存档位开始真实名单的新任期。</p></div>${btn("用真实名单开局","new-game","ghost compact")}</div>`:""}${state.ops.freePlay?'<div class="section-note mb16">自由续玩 · 已保留原战绩与合同，解雇类条件只记录，不再终止任期。</div>':''}${state.event&&tab!=="office"?`<button class="pending-banner" data-action="event">${icon("bell")} 有1项待办需要决定 · 时间已暂停 ${icon("arrow")}</button>`:""}${state.investigation&&!state.ended&&!state.ops.freePlay?'<div class="inline-alert">调查已启动，将于下个结算月裁决。历史记录已经固定，公关无法消除证据。</div>':''}${state.boardWarning&&!state.ended&&!state.ops.freePlay?'<div class="inline-alert">董事会最后通牒：下次月度评估时信心仍低于25，将结束任期。</div>':''}${({office:office,team:teamView,market:marketView,season:seasonView,club:clubView})[tab]()}</main></div>${busy?`<div class="progress-banner"><span class="row gap8"><i class="dot"></i>${esc(progress)}</span>${btn('本场后暂停','stop','compact ghost')}</div>`:''}`;}
  function pageTitle(title,desc,actions=''){return `<div class="page-title"><div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="row">${actions}</div>`:''}</div>`;}
  function stat(label,val,note,ico,color=''){return `<div class="stat"><div class="stat-top">${label}${icon(ico)}</div><div class="stat-value ${color}">${val}</div><div class="stat-note">${note}</div></div>`;}
  function meter(label,value){return `<div><div class="meter-label"><span>${label}</span><b>${Math.round(value)}<span class="muted"> / 100</span></b></div><div class="meter-track"><div class="meter-fill" style="width:${E.clamp(value,0,100)}%;background:${value<30?'#d45b66':value>=65?'#98b49f':'#c6a675'}"></div></div></div>`;}
  function formDots(){return `<div class="form-dots">${state.wins.slice(-5).map(x=>`<span class="form-dot ${x}">${{W:'胜',D:'平',L:'负'}[x]}</span>`).join('')||'<span class="small muted">等待首秀</span>'}</div>`;}
  function eventCard(){const e=state.event;if(!e)return '';return `<section class="event-card"><div class="eyebrow">INBOX · 需要你的决定</div><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p>${btn('打开这份麻烦 '+icon('arrow'),'event','gold-btn compact')}</section>`;}
  function office(){const s=state,r=E.rank(s);return pageTitle('办公室',`${esc(s.name)}，${s.ended?'你的任期已经归档。':'今天也有人等着你作决定。'}`,btn(icon('share')+' 战绩卡','share','ghost compact'))+officeInbox()+directorActions()+officeReports()+operationsPanel()+(s.ended?endPanel():s.phase==='review'?reviewPanel():`<section class="hero"><div class="eyebrow">OLD TRAFFORD · DIRECTOR'S OFFICE</div><h2>${s.phase==='summer'?'长期计划。<br>短期负责人。':s.phase==='winter'?'下半年的希望，<br>请在预算内寻找。':s.noWin>=3?'重建进入新阶段：<br>重新开始。':'这个俱乐部的未来，<br>又轮到你解释了。'}</h2><p>${s.tone?'你想拯救曼联，曼联先把你变成了新闻发布会。':'每周签署经营方案，管理设施、员工与商业承诺。'}</p><div class="hero-flags"><span class="pill red">${phase(s)}</span><span class="pill">董事会目标：前 ${s.target}</span></div>${stadium()}<div class="hero-number" aria-hidden="true">${E.seasonYear(s)}</div></section>`)+`<div class="stats-grid">${stat('可用现金',money(s.cash),`安全储备 ${money(E.safeCash(s).buffer)}`,'wallet')}${stat('联赛排名',s.round?`${r}<span class="label"> / 20</span>`:'—',`${E.team(s).pts} 积分 · ${s.round} 场比赛`,'chart')}${stat('董事会信心',`${Math.round(s.board)}<span class="label"> / 100</span>`,s.board<35?'他们正在重写感谢信':'目前仍然“充分信任”','shield',s.board<35?'negative':'')}${stat('年度账面利润',money(E.profit(s)),'转会费按合同摊销，不等于现金','club',E.profit(s)<0?'negative':'positive')}</div><div class="dashboard-grid"><div class="stack"><section class="card"><div class="card-head"><h2>${['summer','winter'].includes(s.phase)?'经营与转会日程':'下一周事务'}</h2><span class="small muted">${phase(s)}</span></div>${nextPanel()}</section></div><div class="stack"><section class="card"><div class="card-head"><h2>俱乐部温度</h2>${formDots()}</div><div class="meters">${meter('更衣室信任',s.trust)}${meter('球迷支持',s.fans)}${meter('人脉',s.network)}</div><div class="board-note">${s.tone?'“俱乐部仍然很大，主要体现在工资单上。”':`年固定开支 ${money(E.annualExpense(s))}`}</div></section><section class="card"><div class="card-head"><h2>积分榜速览</h2><button class="text-button small muted" data-action="nav" data-tab="season">完整榜单 →</button></div>${leagueTable(E.standings(s).slice(0,5),true)}${r>5?leagueTable([E.team(s)],true):''}</section>${s.phase==='league'?`<section class="card"><div class="card-head"><h2>管理行动</h2><span class="small muted">本周期 ${s.actions}/1</span></div><div class="stack gap8">${btn('更衣室沟通 · 信任 +4','manage','ghost',`data-kind="talk" ${!s.actions?'disabled':''}`)}${btn('对手分析 · €100万','manage','ghost',`data-kind="analysis" ${!s.actions?'disabled':''}`)}${btn('调查泄密','manage','ghost',`data-kind="investigate" ${!s.actions?'disabled':''}`)}${s.gray?btn('虚构灰色交易 · €300万','confirm-bribe','danger',`${!s.actions?'disabled':''}`):''}</div></section>`:''}</div></div>`;}
  function nextPanel(){const s=state;if(s.ended)return `<p class="small"><b>${esc(E.endingInfo(s).label)}</b> · ${esc(E.endingInfo(s).detail)}</p><div class="stack mt16">${s.season<20?btn(s.round===38?'保留球队，开启下一赛季':'保留球队，恢复经营','continue-career','primary'):''}${btn('查看归档详情','end','ghost')}${btn('开始新的任期','new-game','ghost')}</div>`;if(s.phase==='review')return btn('进入下一赛季 '+icon('arrow'),'next-season','primary w100');if(s.event)return `<p class="small muted mb16">${esc(G.info(s).summary)}</p>${btn('打开本周待办','event','primary w100')}`;if(['summer','winter'].includes(s.phase)){const max=s.phase==='summer'?4:2;return `<div class="row between"><div><div class="label">剩余审批额度</div><div class="stat-value">${money(s.windowBudget-s.windowSpent)}</div></div><span class="pill">第 ${s.windowStep+1} / ${max} 轮</span></div><div class="window-steps">${Array.from({length:max},(_,i)=>`<i class="${i<=s.windowStep?'done':''}"></i>`).join('')}</div><p class="small muted mt16 mb16">${s.windowStep===max-1?'这是最后一轮。继续将关闭转会窗，未完成报价会失效。':'挂牌球员后推进窗口，等待买家报价。现金不会因打开下一窗口而重置。'}</p><div class="advance-main">${btn('处理下一批事务 '+icon('arrow'),'advance','primary','data-count="1"')}${btn('查看市场','nav','ghost','data-tab="market"')}</div>`;}
    const fixture=s.fixtures[s.round]?.find(([h,a])=>h===s.playerClub||a===s.playerClub),prev=s.reports[0];if(!fixture)return '<p>赛程已完成，请查看上方赛季交接。</p>';return `<p class="weekly-copy">下一份文件已经在路上。<br><span class="muted">球队交给教练，文件交给你。</span></p><div class="advance-main">${btn('处理下一周事务 '+icon('arrow'),'advance','primary w100','data-count="1"')}</div><p class="event-cadence">${icon('bell')} ${esc(G.cadence(s))}</p><details class="match-background"><summary>本周球场简报 · 联赛第 ${s.round+1} 轮</summary><p class="small muted mt16">${fixture.map(id=>esc(E.club(s,id).name)).join(' vs ')} · ${s.formation} / ${s.tactic}<br>继续推进时自动结算，可在“球队”调整方针。</p>${prev?`<button class="report-row" data-action="report" data-id="${prev.id}"><span class="result ${prev.result}">${{W:'胜',D:'平',L:'负'}[prev.result]}</span><span class="small">上场：${esc(prev.home)} ${prev.hg} : ${prev.ag} ${esc(prev.away)}</span></button>`:''}</details>`;}
  function newsList(list){return list.map(n=>`<article class="news-row"><span class="news-icon">${icon({finance:'wallet',transfer:'market',team:'team',board:'shield',roast:'bell'}[n.type]||'bell')}</span><div><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></div><span class="news-time">第${n.round}轮</span></article>`).join('')||'<p class="empty">暂时没有新的麻烦。</p>';}
  function leagueTable(list,compact=false){return `<table class="league-table"><thead><tr><th>#</th><th>球队</th>${compact?'':'<th>赛</th><th class="hide-mobile">胜</th><th class="hide-mobile">平</th><th class="hide-mobile">负</th><th>净胜</th>'}<th>积分</th></tr></thead><tbody>${list.map(c=>`<tr class="${c.id===state.playerClub?'our-team':''}"><td><span class="rank-chip">${E.standings(state).findIndex(x=>x.id===c.id)+1}</span></td><td class="table-name">${esc(c.name)}</td>${compact?'':`<td>${c.played}</td><td class="hide-mobile">${c.w}</td><td class="hide-mobile">${c.d}</td><td class="hide-mobile">${c.l}</td><td>${c.gf-c.ga>0?'+':''}${c.gf-c.ga}</td>`}<td><b>${c.pts}</b></td></tr>`).join('')}</tbody></table>`;}
  function teamView(){const s=state,own=E.squad(s);return pageTitle('球队','每一份合同，都曾被称为正确决定。',`<span class="pill">${own.length} / 25 人</span>`)+rosterNote()+`<div class="subtabs">${[['roster','一线队'],['tactics','阵容与方针'],['coach','主教练'],['academy','青训'],['people','联络与培养']].map(([k,l])=>`<button class="subtab ${sub===k?'active':''}" data-action="sub" data-sub="${k}">${l}</button>`).join('')}</div>`+(sub==='tactics'?tacticsView():sub==='coach'?coachView():sub==='academy'?academyView():sub==='people'?peopleView():`<section class="card"><div class="card-head"><h2>一线队名单</h2><span class="small muted">点击球员查看合同与操作</span></div><div class="table-wrap"><table class="squad-table"><thead><tr><th>球员</th><th>能力</th><th>状态</th><th class="hide-mobile">年薪</th><th>合同</th></tr></thead><tbody>${own.slice().sort((a,b)=>Object.keys(E.POS).indexOf(a.pos)-Object.keys(E.POS).indexOf(b.pos)||b.ca-a.ca).map(p=>`<tr><td class="table-name"><button class="text-button" data-action="player" data-id="${p.id}"><span class="small"><b>${esc(p.name)}</b> ${s.locked.includes(p.id)?'<span class="gold">◆</span>':''}</span><div class="tiny muted">${E.POS[p.pos]} · ${p.age}岁 ${p.loan?'· 租借':''} ${p.academy?'· 青训':''} ${p.fictional&&E.realWorld(s)?'· 虚构新秀':''}</div></button></td><td><span class="rating ${p.ca<65?'low':p.ca<75?'mid':''}">${p.ca}</span></td><td>${p.injury?`<span class="negative small">伤 ${p.injury}天</span>`:`<span class="small">${Math.round(p.fitness)}%</span><span class="mini-track"><i style="width:${p.fitness}%;background:${p.fitness<65?'#de8e8e':'#a1c8b1'}"></i></span>`}</td><td class="hide-mobile small">${money(p.wage)}</td><td><span class="small ${p.months<=12?'negative':'muted'}">${p.loan?'季末归队':p.months+'个月'}</span></td></tr>`).join('')}</tbody></table></div></section>`);}
  function tacticsView(){const s=state,line=E.lineup(s),str=E.strength(s,s.playerClub);return `<div class="two-col"><section class="card"><div class="card-head"><h2>预计首发</h2><span class="pill">攻 ${str.attack.toFixed(0)} / 防 ${str.defense.toFixed(0)}</span></div><div class="pitch-board"><span class="pitch-center"></span>${['FW','MF','DF','GK'].map(pos=>`<div class="pitch-line">${line.filter(x=>x.pos===pos).map(x=>`<div class="pitch-player"><b>${x.p?x.p.ca:45}</b>${esc(x.p?x.p.name.split('·').pop():'青训应急')}</div>`).join('')}</div>`).join('')}</div><p class="tiny muted mt16">主帅按健康、位置、体能和首发优先级自动排阵。可在球员详情中锁定3名健康球员。</p></section><section class="card"><h2 class="mb16">竞技方针</h2><form id="tactics-form"><div class="form-field"><label for="formation">阵型</label><select id="formation">${['433','4231','442'].map(x=>`<option ${x===s.formation?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="tactic">比赛方针</label><select id="tactic">${['均衡','主动进攻','稳守'].map(x=>`<option ${x===s.tactic?'selected':''}>${x}</option>`).join('')}</select></div><label class="check-label"><input type="checkbox" id="rotate" ${s.rotate?'checked':''}>优先保护体能低于70的球员</label><button type="submit" class="btn primary w100 mt24">提交给主教练</button></form><div class="section-note mt24">主动进攻：攻击 +2，防守 −2，额外消耗体能。<br>稳守：攻击 −2，防守 +2。<br>所有方针都有代价，董事会的口号除外。</div></section></div>`;}
  function coachView(){const s=state,c=s.coach;return `<section class="card mb16"><div class="card-head"><h2>现任主帅 · ${esc(c.name)}</h2><span class="pill">${c.style}</span></div><div class="coach-numbers"><div>执教<b>${c.ability}</b></div><div>培养<b>${c.training}</b></div><div>年薪<b>${money(c.wage)}</b></div><div>合同<b>${c.months}个月</b></div></div><p class="small muted mt16">本季已换帅 ${s.dismissals}/3 次。当前解约金 ${money(c.wage*c.months/12*.5)}。${c.warmup?'尚需'+c.warmup+'场完成磨合。':'主帅已完成磨合。'}</p></section><section class="card"><div class="card-head"><h2>候选主教练</h2><span class="small muted">长期信任，按次计费。</span></div>${s.coachMarket.map((c,i)=>`<div class="coach-card"><div><h3>${esc(c.name)}</h3><div class="small muted">偏好 ${c.style} · 3年合同</div></div><div class="coach-numbers"><div>执教<b>${c.ability}</b></div><div>培养<b>${c.training}</b></div><div>年薪<b>${money(c.wage)}</b></div></div>${btn('接触主帅','coach','compact ghost',`data-index="${i}" ${s.ended?'disabled':''}`)}</div>`).join('')}</section>`;}
  function academyView(){const candidates=(state.academy||[]).map(id=>E.player(state,id)).filter(Boolean);return `<section class="card"><div class="card-head"><h2>青训候选</h2><span class="small muted">每个新赛季最多提拔2人</span></div>${candidates.length?candidates.map(p=>`<div class="coach-card"><div><h3>${esc(p.name)}</h3><div class="small muted">${E.POS[p.pos]} · ${p.age}岁 · 当前 ${p.ca} · ${p.pa-p.ca>=16?'高':'中'}成长空间</div></div>${btn('提拔到一线队','promote','ghost compact',`data-id="${p.id}" ${state.phase!=='summer'?'disabled':''}`)}</div>`).join(''):'<div class="empty">本季没有可提拔的后备球员。前5季仅使用已收录的真实年轻球员，第6季起生成虚构青训。</div>'}</section>`;}
  function marketView(){const s=state,open=['summer','winter'].includes(s.phase),ids=marketFilter==='FREE'?s.freeMarket||[]:s.market,items=ids.map(id=>E.player(s,id)).filter(p=>p&&(marketFilter==='ALL'||marketFilter==='FREE'||p.pos===marketFilter));return pageTitle('转会市场',s.tone?'全欧洲都知道，你正在寻找一个昂贵的答案。':'按位置与预算选择引援目标。',open?btn('推进窗口 '+icon('arrow'),'advance','primary compact','data-count="1"'):'<span class="pill">窗口关闭</span>')+rosterNote()+`<div class="budget-strip"><div><div class="label">本窗剩余额度</div><b>${money(s.windowBudget-s.windowSpent)}</b></div><div><div class="label">俱乐部现金</div><b>${money(s.cash)}</b></div><div><div class="label">球探定向观察</div><b>${s.scans||0} <span class="label">/ 4 次</span></b><span class="tiny muted">前两次免费，其后每次50万</span></div></div>${!open?'<div class="section-note mb16">目前不能买卖球员。可查看报告、调整球队或等待下一个转会窗口。</div>':''}${s.offers.length?`<section class="card mb16"><div class="card-head"><h2>出售报价</h2><span class="pill red">${s.offers.length} 份</span></div>${s.offers.map(o=>`<div class="coach-card"><div><b>${esc(E.player(s,o.player)?.name)}</b><div class="small muted">${esc(E.club(s,o.buyer)?.name)} 报价 ${money(o.fee)}</div></div>${btn('审阅报价','sale','compact primary',`data-id="${o.id}"`)}</div>`).join('')}</section>`:''}<div class="filter-row">${[['ALL','全部推荐'],['FW','前锋'],['MF','中场'],['DF','后卫'],['GK','门将'],['FREE','自由球员']].map(([v,t])=>`<button class="filter-btn ${marketFilter===v?'active':''}" data-action="filter" data-filter="${v}">${t}</button>`).join('')}</div><div class="market-grid">${items.map(p=>{const d=s.marketData[p.id],ca=E.visibleAbility(s,p),stars='★'.repeat(E.star(p))+'☆'.repeat(5-E.star(p));return `<article class="player-card"><div class="player-card-top"><span class="position ${p.pos}">${p.pos} · ${E.POS[p.pos]}</span><div class="player-avatar">${icon('person')}</div></div><div class="player-card-body"><h3>${esc(p.name)}</h3><div class="player-meta">${p.age}岁 · ${esc(E.club(s,p.club)?.name||'自由球员')}</div><span class="identity-tag ${p.realId?'real':'generated'}">${p.realId?'真实球员':'虚构新秀'}</span><div class="player-stars">${stars}</div><div class="player-price"><b>${d.ask?money(d.ask):'自由转会'}</b><span>能力 ${ca.low===ca.high?ca.low:ca.low+'–'+ca.high}</span></div></div><div class="player-card-foot"><span class="tiny muted">${d.scouted?'已完成观察':'球探估计'}</span>${btn('查看目标','target','compact ghost',`data-id="${p.id}"`)}</div></article>`;}).join('')||'<div class="card empty w100">这个位置暂无候选人。</div>'}</div>`;}
  function seasonView(){const s=state;return pageTitle('赛季','积分榜没有公关部门。',formDots())+`<div class="subtabs">${[['table','联赛'],['reports','战报'],['europe','欧战'],['history','任期历史']].map(([k,l])=>`<button class="subtab ${(sub===k||sub==='roster'&&k==='table')?'active':''}" data-action="sub" data-sub="${k}">${l}</button>`).join('')}</div>`+(sub==='reports'?`<section class="card"><div class="card-head"><h2>最近比赛</h2><span class="small muted">保留最近60场完整战报</span></div>${s.reports.map(r=>`<button class="report-row" data-action="report" data-id="${r.id}"><span class="result ${r.result}">${{W:'胜',D:'平',L:'负'}[r.result]}</span><div><div class="small">${esc(r.home)} <span class="muted">vs</span> ${esc(r.away)}</div><div class="tiny muted">${esc(r.label)} · ${E.seasonYear(s,r.season)}/${String(E.seasonYear(s,r.season)+1).slice(-2)}</div></div><span class="scoreline">${r.hg} : ${r.ag}</span></button>`).join('')||'<div class="empty">比赛还没开始，解释还不需要。</div>'}</section>`:sub==='europe'?europeView():sub==='history'?historyView():`<section class="card"><div class="card-head"><h2>架空英超联赛</h2><span class="small muted">38轮 · 前4冠军杯 · 第5–6欧联杯</span></div><div class="table-wrap">${leagueTable(E.standings(s))}</div><p class="tiny muted mt16">这是游戏内简化资格规则。最后3名降级，豪门也不例外。</p></section>`);}
  function europeView(){return `<div class="two-col">${state.europe.map(e=>{const g=e.groups.find(g=>g.some(c=>c.id===state.playerClub));return `<section class="card"><div class="card-head"><h2>${e.name}</h2><span class="pill">${e.finished?'已结束':e.stage}</span></div>${e.ids.includes(state.playerClub)?`<p class="small mb16 ${e.prizePaid&&!e.alive.includes(state.playerClub)&&!e.finished?'negative':'positive'}">${e.finished?e.champion===state.playerClub?'曼联夺冠':'冠军：'+esc(E.club(state,e.champion).name):e.prizePaid?'本季征程已结束，奖金已到账。':'曼联参与本项赛事。'}</p>`:'<p class="small muted mb16">曼联本季未参加此赛事。</p>'}${g?`<table><thead><tr><th>小组</th><th>赛</th><th>净胜</th><th>积分</th></tr></thead><tbody>${g.slice().sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)).map(r=>`<tr class="${r.id===state.playerClub?'our-team':''}"><td>${esc(E.club(state,r.id).name)}</td><td>${r.played}</td><td>${r.gf-r.ga}</td><td>${r.pts}</td></tr>`).join('')}</tbody></table>`:''}${e.alive.length?`<div class="divider"></div><div class="label mb16">${e.finished?'冠军':'仍在争冠'}</div><div class="row wrap">${e.alive.map(id=>`<span class="pill ${id===state.playerClub?'red':''}">${esc(E.club(state,id)?.name)}</span>`).join('')}</div>`:''}<p class="tiny muted mt16">32队 · 8组双循环 · 前2晋级 · 单场淘汰制</p></section>`;}).join('')}</div>`;}
  function historyView(){return `<section class="card"><div class="card-head"><h2>长期计划履历</h2><span class="pill">${state.history.length} 个完整赛季</span></div><div class="table-wrap"><table><thead><tr><th>赛季</th><th>名次</th><th>积分</th><th>利润</th><th>期末现金</th></tr></thead><tbody>${state.history.map(h=>`<tr><td>${E.seasonYear(state,h.season)}/${String(E.seasonYear(state,h.season)+1).slice(-2)}</td><td>${h.rank}</td><td>${h.points}</td><td class="${h.profit<0?'negative':'positive'}">${money(h.profit)}</td><td>${money(h.cash)}</td></tr>`).join('')}</tbody></table></div>${!state.history.length?'<div class="empty">先完成一个赛季，再谈历史评价。</div>':''}</section>`;}
  function clubView(){const s=state,f=s.finance;return pageTitle('俱乐部','你的计划看到了未来，银行只看到了今天。',btn(icon('download')+' 导出存档','export','ghost compact'))+`<div class="two-col"><div class="stack"><section class="card"><div class="card-head"><h2>本季损益</h2><span class="small muted">截至第 ${s.month} 个结算月</span></div>${financial('营业与赛事收入',f.income,'positive')}${financial('工资、运营及其他费用',-f.expense)}${financial('球员资产摊销',-f.amort)}${financial('出售球员账面收益',f.saleProfit)}${financial('账面利润',E.profit(s),E.profit(s)<0?'negative':'positive',true)}<p class="tiny muted mt16">股东注资和借款不计利润。转会费按合同摊销，出售收入扣除剩余账面价值。</p></section><section class="card"><div class="card-head"><h2>信用与贷款</h2><span class="pill">信用 ${s.credit}</span></div>${s.loan?`<p class="small">本金 ${money(s.loan.principal)} · 年利率 ${(s.loan.rate*100).toFixed(1)}%<br>剩余 ${s.loan.remaining} 个月 · 每月付息</p>${btn('提前偿还本金','repay','ghost mt16')}`:`<p class="small muted">信用至少50、无未清贷款且不在整改期，可申请12个月过桥贷款。到期还本，不能借新还旧。</p>${btn('查看借款方案','loan','ghost mt16',s.ended?'disabled':'')}`}</section><section class="card"><div class="card-head"><h2>年度投入</h2><span class="small muted">每年夏窗确定一次</span></div><div class="form-row"><div class="form-field"><label for="scout-level">球探网络</label><select id="scout-level" ${s.invested||s.phase!=='summer'?'disabled':''}>${['基础 · €0','强化 · €300万','深入 · €600万'].map((x,i)=>`<option value="${i}" ${s.scoutLevel===i?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="youth-level">青训培养</label><select id="youth-level" ${s.invested||s.phase!=='summer'?'disabled':''}>${['维持 · €0','加强 · €500万','重点 · €1000万'].map((x,i)=>`<option value="${i}" ${s.youthLevel===i?'selected':''}>${x}</option>`).join('')}</select></div></div>${btn(s.invested?'本年投入已确定':'确定年度投入','invest','primary w100',s.invested||s.phase!=='summer'?'disabled':'')}</section></div><div class="stack"><section class="card"><div class="card-head"><h2>经营约束</h2><span class="pill ${s.probation?'red':''}">${s.probation?'财务整改中':'常规考核'}</span></div>${financial('实际现金',s.cash)}${financial('90天安全储备',E.safeCash(s).buffer)}${financial('年工资及固定运营',E.annualExpense(s))}<div class="divider"></div><div class="meters">${meter('董事会信心',s.board)}${meter('球迷支持',s.fans)}</div><p class="small muted mt16">本季目标前 ${s.target}。连续四季第6或以后、降级、持续现金逾期、重大违规查实都会结束任期。</p></section><section class="card"><div class="card-head"><h2>风险档案</h2><span class="pill ${s.risk?'red':''}">${s.risk}/100</span></div><p class="small muted">${s.cases.length?s.cases.map(c=>esc(c.reason)).join(' · '):'目前没有未了结的违规记录。'}<br>赢球与公关都不能消除证据。</p>${s.gray?`<div class="divider"></div>${financial('总监私人账户',s.privateMoney)}${financial('其中违规所得',s.illicitMoney,s.illicitMoney?'negative':'')}`:''}</section><section class="card"><div class="card-head"><h2>近期资金流水</h2><span class="small muted">单位：欧元</span></div>${s.ledger.slice(0,8).map(l=>`<div class="financial-row"><span class="truncate muted">${esc(l.note)}</span><span class="${['income','sale','loan','capital'].includes(l.kind)?'positive':''}">${['income','sale','loan','capital'].includes(l.kind)?'+':'−'}${money(l.amount)}</span></div>`).join('')||'<p class="small muted">开局现金含首季注资，后续流水逐笔记录。</p>'}</section></div></div>`;}
  function financial(label,amount,cls='',total=false){return `<div class="financial-row ${total?'total':''}"><span>${label}</span><span class="mono ${cls}">${money(amount)}</span></div>`;}
  function nextYear(){return `${E.seasonYear(state)+1}/${String(E.seasonYear(state)+2).slice(-2)}`;}
  function handoffBanner(){if(state.ended&&state.season<20)return `<section class="handoff-banner"><div><b>当前归档：${esc(E.endingInfo(state).label)}</b><span>${esc(E.endingInfo(state).detail)}</span></div>${btn(state.round===38?'保留球队，开启下一赛季':'保留球队，恢复经营','continue-career','primary')}</section>`;return state.phase==='review'&&!state.ended?`<section class="handoff-banner" role="status"><div><b>${year(state)} 已结算 · 任期继续</b><span>奖金已入账；新赛季保留现金、合同与经营回访。</span></div>${btn('进入 '+nextYear()+' 赛季 '+icon('arrow'),'next-season','primary')}</section>`:'';}
  function reviewPanel(){const r=state.review;return `<section class="card season-review"><div class="eyebrow">SEASON HANDOVER · ${year(state)}</div><h2 class="mt16">${esc(r.quote)}</h2><div class="three-col mt16"><div><div class="label">最终名次</div><div class="stat-value">${r.rank}<span class="label"> / 20</span></div></div><div><div class="label">赛季利润</div><div class="stat-value" style="font-size:29px">${money(r.profit)}</div></div><div><div class="label">已处理事务</div><div class="stat-value">${state.ops.seasonHandled}</div></div></div><p class="small muted mt16">联赛奖金 ${money(r.bonus)} 已入账。赛季结束不代表任期结束。</p>${btn('进入 '+nextYear()+' 赛季 '+icon('arrow'),'next-season','primary w100 mt16')}</section>`;}
  function reviewModal(){openModal('赛季结束，任期继续',reviewPanel(),btn('先查看本季账目','close','ghost'));}
  const signed=n=>(n>0?'+':n<0?'−':'')+Math.abs(n).toFixed(2).replace(/\.?0+$/,'');
  function sportNumbers(b){return `攻击 ${signed(b.attack)} · 防守 ${signed(b.defense)}`;}
  function sportingDesk(){const venue=E.nextVenue(state),b=E.sportingImpact(state,venue),active=state.ops.sporting||[];return `<div class="sport-desk"><div class="row between wrap gap8"><b>经营 → 球场</b><span class="pill">${state.phase==='review'||state.ended?'客场基准参考':venue==='home'?'下轮联赛主场':'下轮联赛客场'}</span></div><p class="sport-total ${b.attack+b.defense<0?'negative':'positive'}">${sportNumbers(b)}</p><p class="tiny muted">当前经营状态带来的战力修正。员工支持适用于所有比赛，设施和助威仅用于主场；中立场不享受主场加成。</p>${active.length?`<div class="sport-active">${active.map(e=>`<div class="sport-row"><b>${esc(e.label)}</b><span>${sportNumbers(e)} · 剩余 ${e.remaining} 场${e.scope==='home'?'主场':e.scope==='away'?'客场':'正式比赛'}</span><small>来自：${esc(e.choice)}</small></div>`).join('')}</div>`:'<p class="tiny muted mt16">目前没有临时备战影响。下一次商业活动可能会改变这一点。</p>'}<p class="tiny muted mt16">临时影响按实际出赛扣次数，含欧战；转会窗不消耗次数，同类方案替换旧影响。经营修正每项上限 ±8，不保证赢球。</p></div>`;}
  function sportPreviewHtml(p){if(!p)return '';const e=p.effect;return `<section class="sport-preview"><h3>这项决定怎样影响战绩？</h3>${e?`<p class="sport-path ${e.attack+e.defense<0?'negative':'positive'}">${esc(e.label)} → ${sportNumbers(e)}<br>接下来 ${e.matches} 场${e.scope==='home'?'主场':e.scope==='away'?'客场':'正式比赛'}生效（含欧战）</p><p class="tiny muted">同类备战影响会被本方案替换；没有比赛时不消耗次数。</p>`:''}<div class="sport-comparison"><div><span>主场经营修正</span><b>${sportNumbers(p.home.before)} → ${sportNumbers(p.home.after)}</b></div><div><span>客场经营修正</span><b>${sportNumbers(p.away.before)} → ${sportNumbers(p.away.after)}</b></div></div><p class="tiny muted">这是当前状态下的经营战力变化；上限 ±8。员工影响各场，设施与球迷支持影响主场；信誉通过收入支持投入。阵容、信任和对手也影响赛果。</p></section>`;}
  function latestReport(){const r=state.reports[0];return r&&r.season===state.season&&r.round===state.round&&state.round>0?r:null;}
  function matchLinkHtml(r,compact=false){const b=r.sporting;if(!b)return '<p class="tiny muted">旧战报未记录经营影响；更新后的比赛开始显示。</p>';const swing=b.ourAfter-b.ourBefore-(b.theirAfter-b.theirBefore),drivers=b.rows.filter(x=>x.attack||x.defense).sort((a,c)=>Math.abs(c.attack)+Math.abs(c.defense)-Math.abs(a.attack)-Math.abs(a.defense)).slice(0,compact?1:2);return `<p class="sport-verdict ${swing>0?'positive':swing<0?'negative':''}">${swing>.005?'经营安排改善了本场机会':swing<-.005?'经营安排拖累了本场机会':'本场经营影响接近中性'}</p><p class="small">我方预期进球 ${b.ourBefore.toFixed(2)} → <b>${b.ourAfter.toFixed(2)}</b> · 对手 ${b.theirBefore.toFixed(2)} → <b>${b.theirAfter.toFixed(2)}</b></p><p class="small sport-drivers">${drivers.map(x=>esc(x.label)+"："+sportNumbers(x)).join("<br>")}</p>${compact?'':'<p class="tiny muted">同场条件下，仅移除／加入经营修正的机会对照；不是另一个比分。</p>'}`;}
  function latestMatchPanel(compact=false){const r=latestReport();if(!r)return '';return `<section class="${compact?'weekly-result':'card match-receipt'}"><div class="card-head"><h2>${compact?'最近一场 · 已结算':'最近一场 · 经营回响'}</h2><span class="pill">${esc(r.label)}</span></div><p class="match-score">${esc(r.home)} <b>${r.hg} : ${r.ag}</b> ${esc(r.away)}</p>${matchLinkHtml(r,compact)}${btn('查看本场经营影响','report','ghost compact',`data-id="${r.id}"`)}${compact?'<p class="tiny muted mt16">下面的新方案从之后的比赛生效。</p>':''}</section>`;}
  function sportReportHtml(b){if(!b)return '';return `<section class="sport-report"><h3>你的经营决定如何走上球场</h3><p class="sport-total ${b.attack+b.defense<0?'negative':'positive'}">本场合计：${sportNumbers(b)}</p>${b.rows.map(row=>`<div class="sport-row"><b>${esc(row.label)} · ${sportNumbers(row)}</b><span>${esc(row.detail)}${row.remaining?'（本场赛前）':''}</span><small>相关决定：${esc(row.source)}</small></div>`).join('')}${b.capped?'<p class="tiny muted">已应用 ±8 上限，超过部分不再叠加。</p>':''}<p class="tiny muted mt16">经营影响的是创造与限制机会的能力。正面安排也可能输球，负面安排也可能侥幸赢球。</p></section>`;}
  function directorActions(){return `<section class="director-actions" aria-label="总监行动"><div><b>总监行动</b><span class="tiny muted">${state.ended||state.phase==='review'?'进入赛季后可行动':state.ops.people.lastActionTurn===state.ops.turn?'本周已用 · 推进后恢复':'本周可用1次'} · 可在待办期间安排</span></div>${btn('球员联络人 / 圈内联系人','people','ghost compact')}${btn('球员培养计划','development','ghost compact')}</section>`;}
  function officeReports(){const r=latestReport();return `<details class="card office-reports"><summary>比赛简报${r?' · '+esc(r.home)+' '+r.hg+' : '+r.ag+' '+esc(r.away):' · 暂无比赛'}</summary>${r?latestMatchPanel(): '<p class="small muted mt16">赛果与经营影响将在这里归档。待办弹窗只展示需要你决定的事务。</p>'}${btn('全部赛季战报','reports','ghost compact')}</details>`;}
  function peopleView(){const s=state,p=s.ops.people,l=p.liaison,report=E.liaisonReport(s),used=p.lastActionTurn===s.ops.turn,blocked=s.ended||s.phase==='review'||used,own=E.squad(s),young=own.filter(x=>x.age<=23&&!x.loan&&x.ca<x.pa&&!p.projects.some(y=>y.playerId===x.id)&&!p.completed.some(y=>y.playerId===x.id&&y.season===s.season));return `<section class="card mb16"><div class="card-head"><h2>球员联络人</h2><span class="pill">每季任命1人</span></div><p class="small muted">建立正式联络，收集满意度与队内矛盾。至少这一次，你能听到未经过公关润色的版本。</p>${l?`<h3 class="mt16">${esc(l.name)} · ${l.mode==='open'?'公开联络':'私下监视'}</h3>${meter('联络默契',l.rapport)}<p class="small muted">本季培养 ${l.trained}/2 次；每4轮收到周报。默契60起报告列出具体姓名。</p>${btn('培养联络人 · €50万','train-liaison','primary w100 mt16',blocked||l.trained>=2?'disabled':'')}`:''}${p.appointedSeason!==s.season?`<div class="form-field mt16"><label for="liaison-player">选择球员</label><select id="liaison-player">${own.map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.age}岁</option>`).join('')}</select></div><div class="row wrap">${btn('任命公开联络人 · €20万','appoint-liaison','primary','data-mode="open" '+(blocked?'disabled':''))}${btn('私下监视 · 信任−5','appoint-liaison','danger','data-mode="covert" '+(blocked?'disabled':''))}</div><p class="tiny muted mt16">私下监视同样花费20万，2周后触发队内反噬事件。</p>`:'<p class="tiny muted mt16">本赛季任命额度已使用，下一赛季可更换人选。</p>'}${report?`<div class="people-report"><b>${esc(report.from)} 的报告</b><p>${esc(report.summary)}</p>${report.details.map(t=>`<p class="small muted">${esc(t)}</p>`).join('')}${report.details.length?'':'<p class="small muted">没有发现主力承诺或临近合同的明显矛盾。</p>'}</div>`:''}</section><section class="card mb16"><div class="card-head"><h2>圈内联系人</h2><span class="small muted">每周共用1次总监行动</span></div>${[['scout','马丁 · 独立球探','核实推荐池的一名球员'],['agent','莱昂 · 球员经纪人','提供一名已核实转会目标'],['analyst','伊万 · 对手分析员','下一场攻击+1、防守+2']].map(([k,name,help])=>`<div class="contact-card"><h3>${name}</h3><p class="small muted">熟悉度 ${p.relations[k]}/100 · ${help}</p><div class="row wrap">${btn('联络 · €30万','contact-person','ghost compact',`data-kind="${k}" ${blocked||p.relations[k]>=100?'disabled':''}`)}${btn(k==='analyst'?'请求情报 · €100万':'请求推荐 · €50万','contact-request','primary compact',`data-kind="${k}" ${blocked||p.relations[k]<25?'disabled':''}`)}</div></div>`).join('')}<p class="tiny muted mt16">先联络达到熟悉度25，再提出请求。推荐限每人每窗一次；情报每季4次，同类效果不叠加。</p>${p.recommendedId&&E.player(s,p.recommendedId)&&s.marketData[p.recommendedId]?btn('查看最近推荐','target','ghost mt16',`data-id="${p.recommendedId}"`):''}</section><section class="card" id="development-panel"><div class="card-head"><h2>球员培养计划</h2><span class="pill">同时最多2人</span></div><p class="small muted">投入100万，经过8个健康联赛周后能力+1；期间出场至少3场则+2，不超过潜力。伤病暂停进度，离队终止；每人每季一次。</p>${p.projects.map(plan=>`<div class="people-report"><b>${esc(plan.name)}</b><p>${plan.progress} / ${plan.target} 个健康联赛周 · 已出场 ${Math.max(0,(E.player(s,plan.playerId)?.careerApps||0)-plan.startApps)} 次</p></div>`).join('')}${young.length?`<div class="form-field mt16"><label for="develop-player">选择培养球员</label><select id="develop-player">${young.map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.age}岁 · 能力${x.ca}</option>`).join('')}</select></div>${btn('启动培养 · €100万','start-development','primary w100',blocked||p.projects.length>=2?'disabled':'')}`:'<p class="small muted mt16">目前没有符合条件且尚未培养的年轻球员。</p>'}${p.completed.length?'<div class="divider"></div><h3>最近培养成果</h3>'+p.completed.slice(0,4).map(x=>`<p class="small">${esc(x.name)} · 能力+${x.gain} · 第${x.season}季</p>`).join(''):''}</section>`;}
  function continueCareerModal(){openModal('保留球队继续经营',`<p><b>${esc(E.endingInfo(state).label)}</b>：${esc(E.endingInfo(state).detail)}</p><p>将保留资金、球员、合同与战绩，切换为“自由续玩”。原结束原因会存入记录，之后解雇类条件只记录，不终止任期。20赛季上限仍有效。</p><p>已完成第38轮则直接进入下一赛季；否则恢复当前赛季。</p>`,btn('保留归档','close','ghost')+btn('确认继续经营','continue-career-confirm','primary'));}
  function operationsPanel(){const o=state.ops,impact=E.operatingImpact(state);return `<section class="card operations-panel"><div class="card-head"><div><div class="eyebrow">THE BUSINESS OF REBUILDING</div><h2>俱乐部经营台</h2></div><span class="pill">本季签字 ${o.seasonHandled} 次</span></div>${sportingDesk()}<div class="ops-meters">${meter('设施可靠度',o.stadium)}${meter('员工士气',o.staff)}${meter('商业信誉',o.brand)}</div><p class="small muted mt16">当前每月经营调整：收入 ${money(impact.income)} · 费用 ${money(impact.expense)}<br>设施和员工也影响场上发挥；商业信誉通过收入支持后续投入。设施每月自然损耗1点。</p>${o.queue.length||o.contracts.length?`<details class="ops-commitments"><summary>未来账单与回访 · ${o.queue.length+o.contracts.length} 项</summary>${o.queue.map(q=>`<div class="ops-row"><span>${esc(q.source||"已签方案回访")}</span><b>${q.due<=o.turn?'已到期，排队送达':(q.due-o.turn)+' 周后到期'}</b></div>`).join('')}${o.contracts.map(c=>`<div class="ops-row"><span>${esc(c.name)}<small>剩余 ${c.remaining} 个结算月</small></span><b>${c.income?'+':'−'}${money(c.income||c.expense)}/月</b></div>`).join('')}</details>`:'<p class="tiny muted mt16">暂无后续承诺。珍惜这几秒钟。</p>'}</section>`;}
  async function startNextSeason(){if(busy)return;busy=true;try{const r=E.startNextSeason(state);if(!r.ok){toast(r.message,true);return;}await save();dialog.close();tab='office';sub='roster';render();window.scrollTo(0,0);toast(year(state)+' 已开启。上年的账单也来了。');}finally{busy=false;render();}}
  function endPanel(){const e=state.ended,sc=E.score(state);return `<section class="hero"><div class="eyebrow">END OF TENURE · 第 ${e.season} 年</div><h2>${esc(e.title)}</h2><p><b>${esc(E.endingInfo(state).label)}</b>：${esc(E.endingInfo(state).detail)}</p><p>${e.reason==='relegated'?'你终于让曼联离开了这个让大家失望的联赛。':e.reason==='scandal'?'公关部门已经把你的名字从长期计划中删除。':'董事会充分肯定了这段任期已经结束的事实。'}</p>${state.season<20?btn(state.round===38?'保留球队，开启下一赛季':'保留球队，恢复经营','continue-career','primary mt16'):''}<div class="hero-flags"><span class="pill">声望 ${sc.total}/100</span><span class="pill">${state.trophies.league+state.trophies.cl+state.trophies.el} 座冠军</span></div>${stadium()}</section>`;}
  function rosterNote(){return E.realWorld(state)?`<div class="roster-note"><span>真实名单 · 2026-11-14快照${state.season>=6?' · 新秀已加入':' · 第6季开放虚构新秀'}</span>${btn('资料与规则','roster-info','ghost compact')}</div>`:'';}
  function playerIdentity(p){const fact=E.identityOf(p);return fact?`<div class="player-identity"><span class="identity-tag real">真实球员</span><p><b>${esc(fact.name)}</b></p><p>${esc(fact.nationality||'国籍资料未提供')} · 出生 ${esc(fact.dob)}${fact.jersey?' · 快照球衣号 '+esc(fact.jersey):''}</p><p class="tiny muted">资料快照所属：${esc(fact.clubName)}。年龄随游戏赛季增长；当前效力、合同、能力和估值由游戏模拟。</p><a href="${esc(fact.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看原始球员资料 ↗</a></div>`:`<div class="player-identity"><span class="identity-tag generated">${E.realWorld(state)?'虚构新秀 · 第'+p.generatedSeason+'季生成':'旧版虚构球员'}</span><p class="tiny muted">姓名和个人资料由游戏生成，不对应现实人物。</p></div>`;}
  function rosterInfo(){openModal('球员资料与市场规则',`<p><b>2026/27真实名单开局</b></p><p>名单快照日期为2026-11-14，含${window.MUGARealPlayers.clubs.length}家俱乐部、${window.MUGARealPlayers.clubs.reduce((n,c)=>n+c.players.length,0)}名真实球员，采用ESPN公开阵容资料。曼联一线队选取25人，其他已收录球员进入后备名单。</p><p>姓名、出生日期、位置、国籍来自资料源；能力、潜力、工资、合同年限和报价为游戏平衡设定。游戏中的伤病、交易、事件和战绩不代表真实人物经历。</p><p>前5季转会名单只含真实球员。完成第5季后，每个转会窗加入4名16–19岁虚构新秀；卡片明确标记。真实球员继续年龄增长、转会与退役。</p><p>数据已随游戏打包，游玩不需访问资料网站。旧版任期保留原球员与战绩，真实名单需要新建任期。</p><p><a href="https://www.espn.com/soccer/team/squad/_/id/360" target="_blank" rel="noopener noreferrer">ESPN 曼联名单</a> · <a href="https://www.premierleague.com/en/news/4725682/all-20-premier-league-clubs-squad-numbers-for-202627-season" target="_blank" rel="noopener noreferrer">英超官方2026/27名单</a></p>`,btn('知道了','close','primary'));}
  function playerModal(id){const p=E.player(state,id);if(!p)return;openModal(esc(p.name),`${playerIdentity(p)}<div class="row between mb16"><span class="position ${p.pos}">${E.POS[p.pos]} · ${p.age}岁</span><span class="rating">${p.ca}</span></div><div class="two-col"><div>${financial('年薪',p.wage)}${financial('当前估值',E.value(p))}${financial('剩余账面价值',p.book)}</div><div><div class="financial-row"><span>合同剩余</span><span>${p.months}个月</span></div><div class="financial-row"><span>本季首发 / 健康场次</span><span>${p.starts} / ${p.eligible}</span></div><div class="financial-row"><span>出场承诺</span><span>${p.role}</span></div></div></div><div class="meters mt16">${meter('体能',p.fitness)}${meter('个人士气',p.morale)}</div>${p.injury?`<div class="inline-alert mt16">伤停 ${p.injury} 天</div>`:''}<div class="row wrap mt24">${btn(state.locked.includes(id)?'取消优先首发':'设为优先首发','lock','ghost',`data-id="${id}" ${state.ended?'disabled':''}`)}${!p.loan?btn(state.listed.includes(id)?'撤销挂牌':'挂牌出售','list','ghost',`data-id="${id}" ${state.ended?'disabled':''}`):''}${p.months<=24&&!p.loan?btn('续约3年 · 工资+10%','renew','primary',`data-id="${id}" ${state.ended?'disabled':''}`):''}</div><p class="tiny muted mt16">挂牌不会直接产生收入。转会窗口内推进一轮，等待真实买家报价。</p>`);}
  function targetModal(id){const p=E.player(state,id),m=state.marketData[id];if(!p||!m)return;const ca=E.visibleAbility(state,p),isOpen=['summer','winter'].includes(state.phase);const fee=m.accepted?(m.agreedFee||0):m.ask;openModal(esc(p.name),`${playerIdentity(p)}<div class="row between mb16"><span class="position ${p.pos}">${E.POS[p.pos]} · ${p.age}岁</span><span class="pill">能力 ${ca.low}–${ca.high}</span></div><p>${esc(E.club(state,p.club)?.name||'自由球员')} · ${m.scouted?'球探已完成定向观察。':'能力为球探估计，正式签约后公开精确值。'}</p><div class="row between mt16"><span class="small gold">${'★'.repeat(E.star(p))}</span>${btn(m.scouted?'已观察':'定向观察'+(state.scans<2?' · 免费':' · €50万'),'scout','ghost compact',`data-id="${id}" ${!isOpen||m.scouted||state.scans>=4?'disabled':''}`)}</div><div class="divider"></div>${!m.accepted?`<div class="form-field"><label for="bid">向俱乐部报价 · 当前要价 ${money(m.ask)}</label><input id="bid" type="number" min="0" max="500" step="0.1" value="${m.ask.toFixed(1)}"></div><p class="form-hint">金额单位：百万欧元。已使用 ${m.attempts}/3 次报价。</p>${btn('提交报价','bid','primary w100',`data-id="${id}" ${!isOpen||m.attempts>=3?'disabled':''}`)}`:`<div class="section-note mb16">${fee?'俱乐部已接受 '+money(fee)+' 的转会费。':'自由转会，签字费为一年工资的25%。'}请确认个人合同。</div><div class="form-row"><div class="form-field"><label for="wage">年薪 · 百万欧元</label><input id="wage" type="number" min="${m.wage}" max="50" step="0.1" value="${Math.ceil(m.wage*10)/10}"></div><div class="form-field"><label for="years">合同期限</label><select id="years"><option value="2">2年</option><option value="3">3年</option><option value="4" selected>4年</option><option value="5">5年</option></select></div></div><div class="form-field"><label for="role">出场承诺</label><select id="role"><option>轮换</option><option>主力</option></select></div><p class="form-hint">转会费 ${money(fee)} + ${fee?'5%经纪费':'25%年薪签字费'}。工资计入未来支出；安全线和额度会再次核验。</p>${btn('确认签约','sign','primary w100',`data-id="${id}" ${!isOpen?'disabled':''}`)}`}${p.ca<=79&&p.club!=='free'?`<div class="divider"></div><div class="row between"><div class="small muted">也可租借至季末<br>租借费 ${money(E.value(p)*.1)}，承担70%工资</div>${btn('确认租借','rent','ghost compact',`data-id="${id}" ${!isOpen?'disabled':''}`)}</div>`:''}`);}
  function unreadNews(){const read=state.inboxReadIds||[];return state.news.filter(n=>!read.includes(n.id));}
  function officeInbox(){const unread=unreadNews(),latest=unread[0]||state.news[0],event=state.event,info=event?G.info(state):null;return `<section class="office-inbox ${event?'needs-decision':''}" aria-labelledby="inbox-title"><div class="inbox-heading"><div class="row gap8">${icon('bell')}<h2 id="inbox-title">办公室收件箱</h2><span class="inbox-count">${event?'1项待办':unread.length+'封未读'}</span></div>${btn('查看全部','inbox','ghost compact')}</div>${event?`<div class="inbox-pending"><span class="pause-tag">时间已暂停 · 需要你的决定</span><h3>${esc(event.title)}</h3><p>${esc(info.summary)}</p>${btn('查看原因并作决定 '+icon('arrow'),'event','primary w100')}</div>`:latest?`<button class="inbox-preview" data-action="inbox"><span class="inbox-dot" aria-hidden="true"></span><span><b>${esc(latest.title)}</b><span>${esc(latest.text)}</span></span>${icon('arrow')}</button>`:'<p class="small muted">暂时没有新消息。</p>'}${!event&&!state.ended&&state.phase!=='review'?btn('处理下一周事务 '+icon('arrow'),'advance','primary w100 mt16','data-count="1"'):''}<div class="inbox-bottom"><span>存档 ${activeSlot} · <span data-save-label>${saving}</span></span><span>退出后自动续玩</span></div></section>`;}
  async function inboxModal(){state.inboxReadIds=state.news.map(n=>n.id);await save();render();openModal('办公室收件箱',`${state.event?`<button class="pending-banner" data-action="event">有1项待办未处理：${esc(state.event.title)} ${icon('arrow')}</button>`:''}<div class="section-note">${esc(G.cadence(state))}<br>每周一项经营或球队事务；到期回访优先。新闻通知无需逐条操作。</div>${state.lastDecision?btn('查看最近一次决定的结果','decision-result','ghost w100 mt16'):''}<div class="news-history mt16">${newsList(state.news)}</div>`);}
  function effectRows(rows){return rows.length?rows.map(r=>`<div class="effect-row"><span>${esc(r.label)}</span><b>${r.money?money(r.before):Number(r.before.toFixed(1))} <span aria-hidden="true">→</span> ${r.money?money(r.after):Number(r.after.toFixed(1))}</b></div>`).join(''):'<p class="small muted">没有即时数值变化。</p>';}
  function consequencesHtml(effect){return `${sportPreviewHtml(effect.sporting)}<h3>立即生效</h3>${effectRows(effect.immediate)}<h3 class="mt16">后续影响</h3>${effect.later.length?'<ul class="consequence-list">'+effect.later.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'<p class="small muted">没有额外合同或回访；备战影响见上方。</p>'}`;}
  function eventModal(){const e=state.event;if(!e)return;annotateEvent();selectedOption=null;const info=G.info(state);openModal('待办决定 · '+esc(e.title),`<div class="event-status"><span class="pause-tag">时间已暂停</span><span>${esc(info.source)}</span></div><section class="event-explanation"><h3>为什么现在出现？</h3><p>${esc(info.reason)}</p></section><section class="event-explanation"><h3>发生了什么？</h3><p>${esc(info.summary)}</p>${state.tone?`<blockquote class="event-roast">${esc(e.text)}</blockquote>`:''}</section><h3 class="mt24">选择一个方案</h3><p class="tiny muted">先选方案查看变化，确认后才会执行。</p><div role="radiogroup" aria-label="事件处理方案">${e.options.map((o,i)=>{const effect=G.effects(state,o);return `<button class="option event-option" role="radio" aria-checked="false" data-action="select-event" data-index="${i}" ${effect.unavailable?'disabled':''}><b><span class="option-letter">${String.fromCharCode(65+i)}</span>${esc(o.label)}</b><span>${esc(o.detail.replace(/(?<!球迷)支持/g,'球迷支持').replace(/(?<!更衣室)信任/g,'更衣室信任'))}</span><span class="option-sport">球场联系：${esc(G.sportLink(o))}</span>${effect.unavailable?`<span class="negative">不可选：${esc(effect.unavailable)}</span>`:''}</button>`;}).join('')}</div><div id="event-preview" class="event-preview" hidden></div>`,btn('稍后处理','close','ghost')+btn('先选择方案','confirm-event','primary','id="confirm-event" disabled'));}
  function selectEvent(index){const option=state.event?.options[index];if(!option)return;const effects=G.effects(state,option);if(effects.unavailable)return;selectedOption=index;dialog.querySelectorAll('[data-action="select-event"]').forEach(el=>{const selected=Number(el.dataset.index)===index;el.setAttribute('aria-checked',String(selected));el.classList.toggle('selected',selected);});const preview=$('#event-preview');preview.hidden=false;preview.innerHTML='<h3 class="mb16">方案'+String.fromCharCode(65+index)+' · 结果预览</h3>'+consequencesHtml(effects);const confirm=$('#confirm-event');confirm.disabled=false;confirm.textContent='确认执行方案'+String.fromCharCode(65+index);preview.scrollIntoView({block:'start',behavior:'smooth'});}
  async function confirmEvent(){if(decisionBusy||selectedOption===null||!state.event)return;decisionBusy=true;try{const event=state.event,option=event.options[selectedOption],effects=G.effects(state,option);const r=E.chooseEvent(state,selectedOption);if(!r.ok){modalError(r.message);return;}state.lastDecision={title:event.title,label:option.label,immediate:effects.immediate,later:effects.later,sporting:effects.sporting,season:state.season,round:state.round};await save();render();decisionResult();}finally{decisionBusy=false;}}
  function decisionResult(){const d=state.lastDecision;if(!d)return;openModal('决定已执行',`<div class="decision-confirmed">${icon('check')} ${saveProblem?'已执行，存档待备份':'已执行并自动保存'}</div><h3>${esc(d.title)}</h3><p>你选择了「${esc(d.label)}」。</p><section class="event-preview">${consequencesHtml(d)}</section><p class="tiny muted mt16">本周方案已经生效。继续将处理下一周事务，比赛与月度账单同步结算。</p>`,btn('留在本周','decision-done','ghost')+btn('签收并进入下一周','decision-next','primary'));}
  function reportModal(id){const r=state.reports.find(r=>r.id===id);if(!r)return;openModal(esc(r.label),`<div class="fixture mt16"><div><div class="club-crest ${r.homeId===state.playerClub?'united':''}">${r.homeId===state.playerClub?'M':esc(r.home.slice(0,1))}</div><b>${esc(r.home)}</b></div><div class="fixture-center"><div class="scoreline">${r.hg} : ${r.ag}</div></div><div><div class="club-crest ${r.awayId===state.playerClub?'united':''}">${r.awayId===state.playerClub?'M':esc(r.away.slice(0,1))}</div><b>${esc(r.away)}</b></div></div>${r.pens?`<div class="section-note mb16">点球决胜：${esc(r.pens)} 晋级。</div>`:''}<div class="row between"><span class="small muted">预期进球</span><b class="mono">${r.hx.toFixed(2)} / ${r.ax.toFixed(2)}</b></div><div class="divider"></div>${matchLinkHtml(r)}${sportReportHtml(r.sporting)}${r.reason.map(t=>`<p>· ${esc(t)}</p>`).join('')}${r.injuries.map(t=>`<p class="negative">· ${esc(t)}</p>`).join('')}${state.tone&&r.quote?`<div class="section-note mt24">${esc(r.quote)}</div>`:''}<p class="tiny muted mt16">预期进球表示机会强度。阵容、体能、主帅、经营安排和随机性共同影响比分。</p>`,state.event?btn('返回本周待办','event','primary'):btn('返回办公室','decision-done','primary'));}
  function settingsModal(){openModal('办公室设置',`<div class="form-field"><label for="tone">毒舌强度</label><select id="tone"><option value="2" ${state.tone===2?'selected':''}>董事会原声 · 强讽刺</option><option value="0" ${!state.tone?'selected':''}>只看账 · 减少吐槽</option></select></div><p class="form-hint">只调整文字显示，不改变比赛随机结果。</p><div class="row wrap">${btn('保存设置','save-settings','primary')}${btn(icon('download')+' 导出备份','export','ghost')}${btn(icon('upload')+' 导入备份','import','ghost')}</div><div class="divider"></div><h3>三个独立存档</h3><div class="stack mt16">${[1,2,3].map(n=>{const sl=slots.find(x=>x.id===n);return `<div class="slot-card ${n===activeSlot?'active':''}"><div class="row between"><div><div class="small">存档 ${n}${n===activeSlot?' · 当前':''}</div><div class="tiny muted">${sl?esc(sl.state.name)+' · '+year(sl.state)+' · '+phase(sl.state):'空存档'}</div></div>${sl?btn('读取','load','ghost compact',`data-slot="${n}"`):''}</div>${sl?.previous?`<button class="text-button tiny muted mt16" data-action="restore" data-slot="${n}">恢复上一个成功保存节点</button>`:''}</div>`;}).join('')}</div><div class="divider"></div><div class="row wrap">${btn('资料与名单规则','roster-info','ghost')}<a class="btn ghost" href="muga-offline.html" download="MUGA离线版.html">下载免联网版本</a>${btn('复制备份文本','backup-text','ghost')}${btn('粘贴备份导入','paste-backup','ghost')}${btn('新建任期','new-game','ghost')}${btn('主动退休','confirm-retire','danger',state.ended?'disabled':'')}</div><p class="tiny muted mt16">重新打开会自动续玩上次任期，比赛和决定均即时保存。存档留在此浏览器；清理数据或换设备前请导出备份。若手机无法选文件，可复制备份文本并粘贴导入。当前版本 v0.6。离线版与在线版的存档互相独立，可通过导入迁移。</p>`);}
  function helpModal(){openModal('上任指南',`<div class="help-list"><div><b>01 · 先处理本周文件</b><p>每周必有一项事务，大部分来自俱乐部运营。先看情况和触发原因，再选方案、预览后果并确认。夏窗4步、冬窗2步也有经营事务；需要时可自主买卖球员。</p></div><div><b>02 · 决策完毕就推进</b><p>选择会改变设施、员工士气和商业信誉，影响每月收入与费用。员工影响备战，设施和球迷支持影响主场。商业活动、维护或裁员还可能带来持续数场的临时战力影响。部分方案会签下经营合同，或在3周后带来新的回访决定。签收后可以直接进入下一周；比赛由教练同步带队完成；赛果集中在办公室的折叠比赛简报和赛季战报，待办只展示当前事务。总监行动可任命及培养球员联络人、维护圈内联系人、请求情报与安排球员培养。</p></div><div><b>03 · 现金和利润是两本账</b><p>转会费即时付款，按合同月数摊销。新承诺要保留三个月工资与运营储备；出售回款的80%可增加当窗额度。</p></div><div><b>04 · 别只看积分榜</b><p>董事会信心低于25会给出整改预警，下月仍不达标就结束任期。连续四季第6或以后、降级、逾期和重大违规也会失败。</p></div><div><b>05 · 赛季结束，任期继续</b><p>第38轮后弹出交接单，点击“进入下一赛季”继续；各页面顶部也保留入口。异常归档按赛季证据修复；真实结局显示原因，可保留球队切换自由续玩。退出后重新打开会自动续玩。右上角设置可切换3个存档、导出或导入。战绩卡可保存成图片。新开局采用真实身份资料，比赛、合同和事件属于虚构模拟；前5季仅真实球员，第6季加入虚构新秀。旧版任期保持原球员。</p></div></div><div class="section-note">你最多拥有20个赛季。曼联已经证明，时间本身解决不了问题。</div>`);}
  async function advance(count){if(busy)return;if(state.event){eventModal();return;}if(state.ended)return;if(state.phase==='review'){await startNextSeason();return;}if(['summer','winter'].includes(state.phase)){const max=state.phase==='summer'?4:2;if(state.windowStep===max-1){openModal('关闭转会窗口',`<p>继续后转会窗将关闭，未完成报价与出售报价失效。你的现有合同、工资和负债会继续生效。</p><div class="section-note mt16">当前阵容 ${E.squad(state).length} 人 · 现金 ${money(state.cash)}</div>`,btn('再看看','close','ghost')+btn('确认关闭并继续','advance-confirm','primary'));return;}}await runAdvance(count);}
  async function runAdvance(count){if(busy)return;busy=true;stop=false;const startPhase=state.phase;dialog.close();try{for(let i=0;i<count;i++){progress=`正在结算 · ${phase(state)}`;render();await new Promise(r=>setTimeout(r,35));if(stop||document.hidden)break;const r=E.next(state);if(!r.ok){toast(r.message,true);break;}const saved=await save();if(!saved||stop||state.event||state.ended||state.phase!==startPhase||state.pauseReason)break;}}catch(err){console.error(err);toast('推进未完成：'+err.message+'。可以从设置恢复上一存档。',true);}finally{busy=false;render();if(state.event)eventModal();else if(state.ended)endModal();else if(state.phase==='review')reviewModal();else if(state.pauseReason)toast(state.pauseReason);}}
  function endModal(){const s=state,sc=E.score(s);openModal(esc(s.ended.title),`<p class="section-note"><b>${esc(E.endingInfo(s).label)}</b>：${esc(E.endingInfo(s).detail)}</p>${s.season<20?btn(s.round===38?'保留球队，开启下一赛季':'保留球队，恢复经营','continue-career','primary w100 mt16'):''}<p>从 ${year({...s,season:1})} 到 ${year(s)}，你为下一任留下了一段可以查账的历史。</p><div class="stats-grid" style="grid-template-columns:1fr 1fr">${stat('最终声望',sc.total+'/100','竞技、财务、青训与操守','trophy')}${stat('冠军总数',s.trophies.league+s.trophies.cl+s.trophies.el,'联赛、冠军杯与欧联杯','trophy')}</div><div class="section-note">感谢你对俱乐部作出的贡献。具体贡献将在措辞审查后补充。</div>`,btn('查看完整任期','close','ghost')+btn('生成战绩卡','share','primary'));}
  function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  function exportSave(){download(new Blob([E.serializeSave(state)],{type:'application/json'}),`MUGA-${state.name.replace(/[\\/:*?"<>|]/g,'')}-${year(state).replace('/','-')}.json`);toast('已导出存档。换设备后可导入继续。');}
  function prepareImport(raw){try{const parsed=window.MUGABackup.parse(raw),free=[1,2,3].find(n=>!slots.some(s=>s.id===n));openModal('导入存档',`${parsed.warnings.length?'<p class="section-note">部分备份记录无效；下方列出可恢复的任期。</p>':''}<div class="form-field"><label for="import-record">选择备份中的任期</label><select id="import-record">${parsed.records.map((r,i)=>`<option value="${i}">${esc(r.state.name)} · ${year(r.state)} · ${phase(r.state)}</option>`).join('')}</select></div><div class="form-field"><label for="import-slot">写入存档位置（已有内容将被替换）</label><select id="import-slot">${[1,2,3].map(n=>`<option value="${n}" ${n===(free||activeSlot)?'selected':''}>存档 ${n} · ${slots.some(x=>x.id===n)?'已有任期':'空'}</option>`).join('')}</select></div><p class="tiny muted">确认前不会修改现有存档。</p>`,btn('取消','close','ghost')+'<button id="confirm-import" class="btn primary">确认导入</button>');$('#confirm-import').onclick=async()=>{activeSlot=Number($('#import-slot').value);state=parsed.records[Number($('#import-record').value)].state;tab='office';const persisted=await save();dialog.close();render();window.scrollTo(0,0);if(!persisted){toast('备份已读取，但浏览器未能保存；请保持页面打开并导出备份。',true);return;}toast(state.ops.archiveRecovery?'备份已导入，异常归档已恢复为赛季交接。':'备份已导入，进度已恢复。');};}catch(err){openModal('备份未导入',`<p role="alert">${esc(err.message)}</p><p class="small muted">现有存档没有被替换。可重新选择JSON文件，或粘贴完整备份文本。</p>`,btn('重新选文件','import','primary')+btn('粘贴导入','paste-backup','ghost'));}}
  function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,.txt,application/json,text/plain';input.hidden=true;document.body.append(input);input.oncancel=()=>input.remove();input.onchange=async()=>{const file=input.files?.[0];input.remove();if(!file)return;if(file.size>12e6){openModal('备份未导入','<p>文件超过12MB，请选择单个游戏JSON备份。</p>',btn('重选文件','import','primary'));return;}try{prepareImport(await file.text());}catch(err){openModal('无法读取文件',`<p>${esc(err.message)}</p><p>可改用备份文本导入。</p>`,btn('粘贴导入','paste-backup','primary'));}};input.click();}
  function pasteBackup(){openModal('粘贴备份导入','<div class="form-field"><label for="backup-input">完整JSON备份</label><textarea id="backup-input" rows="9" placeholder="粘贴从设置中复制的备份文本"></textarea></div>',btn('取消','close','ghost')+btn('读取备份','parse-backup','primary'));}
  function backupText(){openModal('备份文本',`<p class="small muted">可全选复制，保存为文本文件，或在另一台设备粘贴导入。</p><textarea id="backup-output" rows="9" readonly>${esc(E.serializeSave(state))}</textarea>`,btn('关闭','close','ghost')+btn('复制全部','copy-backup','primary'));}
  function shareModal(){const s=state,c=document.createElement('canvas');c.width=900;c.height=1140;const ctx=c.getContext('2d');ctx.fillStyle='#171719';ctx.fillRect(0,0,900,1140);const g=ctx.createLinearGradient(0,0,900,600);g.addColorStop(0,'#842638');g.addColorStop(1,'#2d1c23');ctx.fillStyle=g;ctx.fillRect(0,0,900,430);ctx.fillStyle='#edc4ad';ctx.font='bold 25px "Microsoft YaHei", sans-serif';ctx.fillText('M U G A  /  任 期 成 绩 单',65,75);ctx.fillStyle='#fff4e8';ctx.font='bold 58px "Microsoft YaHei", sans-serif';ctx.fillText(s.ended?'长期计划已归档':'长期计划仍在施工',65,170);ctx.font='25px "Microsoft YaHei", sans-serif';ctx.fillStyle='#d5b9b8';ctx.fillText(`${s.name} · ${year(s)} · 第${s.season}年`,65,232);ctx.font='22px "Microsoft YaHei", sans-serif';ctx.fillText('董事会正在准备它一直支持你的证据。',65,320);const metrics=[['冠军总数',String(s.trophies.league+s.trophies.cl+s.trophies.el)],['当前 / 最后排名',String(E.rank(s))],['任期声望',E.score(s).total+'/100'],['俱乐部现金',money(s.cash)]];metrics.forEach(([label,val],i)=>{const x=65+(i%2)*400,y=500+Math.floor(i/2)*180;ctx.font='22px "Microsoft YaHei", sans-serif';ctx.fillStyle='#a9a6a5';ctx.fillText(label,x,y);ctx.font='bold 49px "Microsoft YaHei", sans-serif';ctx.fillStyle='#e6c28b';ctx.fillText(val,x,y+75);});ctx.strokeStyle='#444046';ctx.beginPath();ctx.moveTo(65,860);ctx.lineTo(835,860);ctx.stroke();ctx.font='23px "Microsoft YaHei", sans-serif';ctx.fillStyle='#d5cdca';ctx.fillText(`真实支付解约金 ${money(s.severance)}`,65,920);ctx.fillText(`落空承诺 ${s.careerFailedPromises} 次 · 重建声明 ${s.statementCount} 次`,65,963);ctx.fillStyle='#818087';ctx.font='19px "Microsoft YaHei", sans-serif';ctx.fillText('真实名单 / 虚构经营 · 本地游戏记录',65,1070);shareCanvas=c;openModal('这次解释，配张图',`<img class="share-preview" src="${c.toDataURL('image/png')}" alt="MUGA 任期战绩卡预览"><p class="tiny muted">图片只包含上方预览信息，不包含完整存档。站点访问范围沿用当前分享设置。</p>`,btn('复制同种子挑战链接','copy-link','ghost')+btn(icon('download')+' 保存战绩图片','save-card','primary'));}
  async function copyLink(){const u=new URL(location.href);u.search='';u.searchParams.set('seed',state.seed);u.searchParams.set('difficulty',state.difficulty);u.searchParams.set('gray',state.gray?'1':'0');try{await navigator.clipboard.writeText(u.href);toast('挑战链接已复制，只包含开局条件，不包含你的存档。');}catch{openModal('同种子挑战链接',`<p class="small">此链接只复制开局条件，不包含存档；访问范围沿用站点分享设置。</p><div class="form-field mt16"><input value="${esc(u.href)}" readonly onclick="this.select()" aria-label="挑战链接"></div>`);}}
  document.addEventListener('submit',async event=>{if(event.target.id==='new-game-form'){event.preventDefault();const options={name:$('#director-name').value.trim()||'新任总监',background:$('#background').value,style:$('#style').value,difficulty:$('#difficulty').value,seed:$('#seed').value||'MUGA-2026',gray:$('#gray').checked};const chosen=Number($('#slot').value);const begin=async()=>{activeSlot=chosen;state=E.createGame(options);tab='office';sub='roster';await save();if(dialog.open)dialog.close();render();window.scrollTo(0,0);toast('任命已生效。点击处理事务，开始签字背锅。');};if(slots.some(s=>s.id===chosen)){openModal('替换已有任期',`<p>存档 ${chosen} 已有游戏。确认后将用新任期替换，建议先导出旧档。</p>`,btn('取消','close','ghost')+'<button id="confirm-new" class="btn primary">确认替换</button>');$('#confirm-new').onclick=begin;}else await begin();}if(event.target.id==='tactics-form'){event.preventDefault();await commit(E.setTactics(state,$('#formation').value,$('#tactic').value,$('#rotate').checked));}});
  document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;if(decisionBusy||busy&&!['stop','close'].includes(action))return;try{
    if(action==='roster-info'){rosterInfo();return;}if(action==='people'||action==='development'){if(dialog.open)dialog.close();tab='team';sub='people';render();if(action==='development')$('#development-panel').scrollIntoView({block:'start'});else window.scrollTo(0,0);return;}if(action==='reports'){tab='season';sub='reports';render();window.scrollTo(0,0);return;}if(action==='continue-career'){continueCareerModal();return;}if(action==='continue-career-confirm'){await commit(E.continueArchived(state),{close:true});tab='office';render();window.scrollTo(0,0);return;}if(action==='appoint-liaison'){await commit(E.appointLiaison(state,$('#liaison-player').value,el.dataset.mode));return;}if(action==='train-liaison'){await commit(E.trainLiaison(state));return;}if(action==='contact-person'){await commit(E.contactPerson(state,el.dataset.kind));return;}if(action==='contact-request'){await commit(E.requestContact(state,el.dataset.kind));return;}if(action==='start-development'){await commit(E.startDevelopment(state,$('#develop-player').value));return;}if(action==='paste-backup'){pasteBackup();return;}if(action==='backup-text'){backupText();return;}if(action==='parse-backup'){prepareImport($('#backup-input').value);return;}if(action==='copy-backup'){try{await navigator.clipboard.writeText($('#backup-output').value);toast('备份文本已复制。');}catch{$('#backup-output').focus();$('#backup-output').select();toast('请长按文本复制。');}return;}
    if(action==='close'){dialog.close();return;}if(action==='help'){helpModal();return;}if(action==='stop'){stop=true;return;}
    if(action==='nav'){tab=el.dataset.tab;sub=tab==='season'?'table':'roster';render();window.scrollTo(0,0);return;}
    if(action==='sub'){sub=el.dataset.sub;render();return;}if(action==='filter'){marketFilter=el.dataset.filter;render();return;}
    if(action==='inbox'){await inboxModal();return;}if(action==='select-event'){selectEvent(Number(el.dataset.index));return;}if(action==='confirm-event'){await confirmEvent();return;}if(action==='decision-result'){decisionResult();return;}if(action==='decision-done'){dialog.close();tab='office';render();window.scrollTo(0,0);return;}if(action==='event'){eventModal();return;}if(action==='settings'){settingsModal();return;}if(action==='player'){playerModal(id);return;}if(action==='target'){targetModal(id);return;}if(action==='report'){reportModal(id);return;}if(action==='end'){endModal();return;}
    if(action==='share'){shareModal();return;}if(action==='save-card'){shareCanvas?.toBlob(b=>b&&download(b,'MUGA-任期战绩.png'));return;}if(action==='copy-link'){await copyLink();return;}if(action==='export'){exportSave();return;}if(action==='import'){importSave();return;}
    if(action==='new-game'){checkpoint();if(dialog.open)dialog.close();state=null;showSetup();window.scrollTo(0,0);return;}
    if(action==='load'||action==='restore'){const sl=slots.find(s=>s.id===Number(el.dataset.slot));if(!sl)return;const candidate=action==='restore'?sl.previous:sl.state;if(!candidate)return;state=E.validateSave(JSON.parse(JSON.stringify(candidate)));activeSlot=sl.id;tab='office';if(dialog.open)dialog.close();if(action==='restore')await save();else saves.activate(activeSlot);render();window.scrollTo(0,0);toast('任期已读取。');return;}
    if(action==='next-season'){await startNextSeason();return;}if(action==='decision-next'){dialog.close();tab='office';await advance(1);return;}
    if(action==='advance'){await advance(Number(el.dataset.count)||1);return;}if(action==='advance-confirm'){await runAdvance(1);return;}
    if(action==='scout'){if(await commit(E.scout(state,id),{quiet:true}))targetModal(id);return;}
    if(action==='bid'){const result=E.offerTransfer(state,id,Number($('#bid').value));await save();render();targetModal(id);if(!result.ok)modalError(result.message);else toast(result.message);return;}
    if(action==='sign'){const r=E.signPlayer(state,id,{wage:Number($('#wage').value),years:Number($('#years').value),role:$('#role').value});if(await commit(r,{close:true})){if(state.event)eventModal();}return;}
    if(action==='rent'){await commit(E.loanPlayer(state,id),{close:true});return;}
    if(action==='lock'){if(await commit(E.lockPlayer(state,id),{quiet:true}))playerModal(id);return;}
    if(action==='list'){await commit(E.listPlayer(state,id),{close:true});return;}
    if(action==='renew'){await commit(E.renew(state,id,3),{close:true});return;}
    if(action==='promote'){await commit(E.promote(state,id));return;}
    if(action==='sale'){const o=state.offers.find(x=>x.id===id),p=E.player(state,o.player);openModal('出售报价确认',`<p>${esc(E.club(state,o.buyer).name)} 愿意支付 <b>${money(o.fee)}</b> 签下 ${esc(p.name)}。</p><div class="mt16">${financial('现金到账',o.fee)}${financial('回补审批额度',o.fee*.8)}${financial('账面出售收益',o.fee-p.book)}</div><p class="tiny muted mt16">球员仍可能拒绝转会。只有成交才入账。</p>`,btn('稍后','close','ghost')+btn('接受报价','sell','primary',`data-id="${id}"`));return;}
    if(action==='sell'){await commit(E.sellPlayer(state,id),{close:true});return;}
    if(action==='coach'){const i=Number(el.dataset.index),c=state.coachMarket[i],fee=state.coach.wage*state.coach.months/12*.5;openModal('确认更换主教练',`<p>任命 ${esc(c.name)}，执教能力${c.ability}，偏好${c.style}。</p><div class="mt16">${financial('现任主帅解约金',fee)}${financial('新主帅年薪',c.wage)}</div><p class="section-note mt16">前4场有磨合影响。本季换帅次数将变为 ${state.dismissals+1}/3。不会重置董事会目标。</p>`,btn('保持信任','close','ghost')+btn('确认任命','hire','primary',`data-index="${i}"`));return;}
    if(action==='hire'){await commit(E.hireCoach(state,Number(el.dataset.index)),{close:true});return;}
    if(action==='manage'){if(await commit(E.management(state,el.dataset.kind))&&state.event)eventModal();return;}
    if(action==='confirm-bribe'){openModal('虚构掮客的灰色提议','<p>费用300万欧元。60%无效果，40%使下场预期进球增加0.3；无论是否有效，违规风险+30。重大行为被调查查实将结束任期。</p>',btn('拒绝','close','ghost')+btn('确认承担风险','bribe','danger'));return;}
    if(action==='bribe'){await commit(E.management(state,'bribe'),{close:true});return;}
    if(action==='invest'){await commit(E.invest(state,Number($('#scout-level').value),Number($('#youth-level').value)));return;}
    if(action==='loan'){openModal('申请过桥贷款',`<p>最高 ${money(Math.min(50,state.baseRevenue*.1))}，期限12个月。年利率 ${((Math.max(.06,.1-.001*(state.credit-50)))*100).toFixed(1)}%。到期还本，不可借新还旧。</p><div class="form-field mt16"><label for="loan-amount">借款金额 · 百万欧元</label><input id="loan-amount" type="number" min="1" max="50" value="30"></div>`,btn('取消','close','ghost')+btn('确认借款','take-loan','primary'));return;}
    if(action==='take-loan'){await commit(E.takeLoan(state,Number($('#loan-amount').value)),{close:true});return;}if(action==='repay'){await commit(E.repayLoan(state));return;}
    if(action==='save-settings'){state.tone=Number($('#tone').value);await commit({ok:true,message:'设置已保存。经营随机状态未改变。'},{close:true});return;}
    if(action==='confirm-retire'){openModal('提前退出责任认定','<p>主动退休会结束当前任期并生成结局，不能继续推进。可先导出备份。</p>',btn('继续负责','close','ghost')+btn('确认退休','retire','danger'));return;}if(action==='retire'){await commit(E.retire(state),{close:true});endModal();return;}
  }catch(err){console.error(err);toast('操作未完成：'+err.message,true);}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){stop=true;checkpoint();}});
  window.addEventListener('pagehide',()=>{stop=true;checkpoint();});
  (async()=>{slots=await saves.init();const last=saves.resume();if(last){state=last.state;activeSlot=last.id;annotateEvent();render();window.scrollTo(0,0);toast(last.recovered?'已恢复上一份完整存档。':'已自动续玩：'+year(state)+' · '+phase(state)+'。');}else showSetup();if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol)){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(()=>{});}})();
})();
